G=load()
from collections import deque
def enc(g,color_val):
    h,w=g.shape
    seen=np.zeros((h,w),bool); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r,c]!=color_val and not seen[r,c]: seen[r,c]=True;q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r,c]!=color_val and not seen[r,c]: seen[r,c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not seen[nr,nc] and g[nr,nc]!=color_val:
                seen[nr,nc]=True;q.append((nr,nc))
    rem = g!=color_val & ~seen
    return rem
